    id_auditor INT PRIMARY KEY,
    nome VARCHAR(80) NOT NULL,
    id_ug INT,
    remuneracao DECIMAL(10,2) CHECK (remuneracao > 0),
    FOREIGN KEY (id_ug) REFERENCES unidade_gestora(id_ug)
);
